DELETE FROM `quest_greeting_locale` WHERE `ID` = 234 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (234,0,'zhTW','一股邪惡的腐化已經悄悄滲入了西部荒野。當我在羅德隆的戰場上盡忠職守時，這些老實的農莊卻遭到了洗劫，變成了流氓與殺手的藏身之處。人民民兵團需要你的幫助。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 235 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (235,0,'zhTW','歡迎來到我們簡陋的家!能看到一張友善的面孔真好。你的臂膀真是強壯。我丈夫和我一直在尋找能在農場幫忙的人手。既然大部分的好人都已經離開了，要找到一個能幹的人來幫忙可真不容易。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 238 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (238,0,'zhTW','有時候我覺得天上懸著一片巨大的灰雲，不斷地把厄運降臨在我們頭上。先是我們被趕出了自己的土地，現在連西部荒野都出不去了。一切都亂糟糟的。得想想辦法才行。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 239 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (239,0,'zhTW','我從遠近各地冒險而來$b遇見形形色色的古怪傢伙$b但若你想問我問題$b得先完成一個簡單的任務!',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 240 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (240,0,'zhTW','唉，光是要在這裡維持秩序就已經夠難的了，還不斷冒出新麻煩!希望你帶來的是好消息，$n……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 241 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (241,0,'zhTW','嘿，朋友。我叫雷米。我從東邊的赤脊山來，到這裡找生意做，找生意做。你有沒有……有沒有什麼？？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 261 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (261,0,'zhTW','你好，市民。你看起來像是個$g有目標的男人:有目標的女人;——你是來找暴風城軍隊辦事的嗎？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 265 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (265,0,'zhTW','我早已感應到你的到來，$n。這是寫在星辰的軌跡之中的。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 272 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (272,0,'zhTW','哈囉，哈囉!歡迎來到我的廚房，$g先生:女士;!緋紅烏鴉旅店最美味的佳肴都是在這裡做出來的。啊，聞聞這美妙的香氣!',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 278 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (278,0,'zhTW','你好，親愛的$g先生:女士;。坐下來吧，如果你餓了就吃點東西。別在意我正忙著做針線活——我在聽你說話……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 342 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (342,0,'zhTW','你好，$N!歡迎來到我簡陋的花園。最近的天氣一直很不錯。希望它能繼續保持穩定，好讓我們有個豐收的季節。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 344 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (344,0,'zhTW','是誰在暴風城王國的拉克夏爾法庭前？在這個城鎮裡表明你的來意，$R。獸人對王國的威脅太過重大，容不得我們浪費時間閒聊。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 381 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (381,0,'zhTW','幸會了，$C。如果你是來談生意的，那就先弄杯酒，我們再好好聊聊。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 382 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (382,0,'zhTW','我沒空閒聊，市民，不過如果你願意幫我們對付獸人，我會找到你的用武之地。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 392 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (392,0,'zhTW','別驚慌，$r。我早已離開了人世，但我對你們這樣的生靈毫無惡意。我這一生見過太多死亡了。如今我唯一的心願就是和平。或許你能幫助我達成這個心願。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 415 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (415,0,'zhTW','嘿，$G夥計:女士;，你能不能幫我個忙？我現在真的是走投無路了……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 464 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (464,0,'zhTW','你好，$C。這是艱難的時代啊，朋友，我們的城鎮正遭受圍攻!黑石獸人從石衛堡壘發起攻擊，暗影獸人在伊爾加拉塔樓虎視眈眈，赤脊山地鼠人群也正在集結力量。希望你不是來度假的……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 633 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (633,0,'zhTW','黑暗的時代已經降臨，$c……我們很快就會失去一切……到那時，聖光將會捨棄所有人，只留下真正走在聖光之下的人。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 656 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (656,0,'zhTW','到處都是盜賊!$b$b太可怕了。洞穴整個塌陷在我們身上。我想礦業公司的人都死光了，包括我哥哥，那個工頭。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 661 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (661,0,'zhTW','你好。你與凱爾文家族有什麼事嗎？你是要來幫助凱爾文家對抗不死族嗎？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 714 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (714,0,'zhTW','你好，$c!今天真是打獵的好日子，你說是吧？我獵野豬的運氣一直都不錯。你要不要也試試看？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 733 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (733,0,'zhTW','在這附近走路小心點，$G小子:小妞;。你雖然不是我們這夥的，但這不代表你亂來我就不會用棍子教訓你!',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 737 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (737,0,'zhTW','哦，你好啊。你看起來不像是會拒絕賺點錢的人，嗯？我從你的眼神就看得出來。我是魔高·凱伯克，艾澤拉斯營運部門的監督者，如果你想要的是財富，或許我可以幫你安排安排。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 773 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (773,0,'zhTW','$C，是吧？我是克拉茲克，里維加茲大財主的秘書。這片叢林內外發生的一切我都一清二楚。你會不會有興趣知道棘齒城目前的石油行情？不感興趣？那想找份工作嗎？這方面我倒是能幫上忙。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 786 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (786,0,'zhTW','你好，$g小伙子:姑娘;。我是格瑞林·白鬚。我在這裡是為了調查寒脊谷日益增多的巨魔所造成的威脅。我發現了什麼？有點令人擔憂……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 823 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (823,0,'zhTW','你好，$c。平時我應該是在外面巡邏，照看暴風城的百姓，但現在許多暴風城衛兵都被派往其他地方作戰。所以我就被任命在這裡發放賞金，儘管我更想去巡邏……',0);
