INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1071,0,'zhTW','如果說時間教會了我一件事，那就是沒有一項任務是無聊的。守衛桑多爾橋原本應該是件輕鬆的差事。但大部分軍隊都在前線與聯盟並肩作戰，我們在這裡寡不敵眾，鄧莫多已經淪陷了。',0);
