INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1343,0,'zhTW','哎呀，這不是個血氣方剛的年輕$c嗎，想必是聽聞了我在戰場上的功績才來的吧!$B$B現在沒空講故事了，因為還有偉大而重要的事情等著去做!所以如果你正在尋求榮耀，那今天算你走運……',0);
