INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2216,0,'zhTW','我們距離研發出黑暗女士如此渴望的新瘟疫，已經只有一步之遙了。',0);
