INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2263,0,'zhTW','希望你是來工作的，$C。我們有很多事要做，而部落、辛迪加和食人魔是不會來幫我們的。',0);
