INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2498,0,'zhTW','什麼什麼？!我們都得賺錢……而站著閒晃可賺不到錢。',0);
