INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2700,0,'zhTW','我們在庇護點守著阿拉希高地僅存的少數斯特隆加德領土。而我們正在節節敗退……$B$B如果你有話要對我說，希望是好消息。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2706 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2706,0,'zhTW','多虧了酋長，即使身處我們昔日監獄的廢墟之中，希望仍然存在，部落正在重新崛起。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2713 AND `type` = 1 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2713,1,'zhTW','這塊木板上貼滿了粗製濫造的通緝海報。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2785 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2785,0,'zhTW','退後!退後!我身上有一整包爆炸粉，我可不怕用它!我要把我們全都炸上天!$B$B哦，算了。我還以為你是別人……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2786 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2786,0,'zhTW','歡迎來到骨握的符文與末日之店，$c。你可以看，但不可以摸。$B$B這裡有些知識並不是給……未經啟蒙者準備的。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2817 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2817,0,'zhTW','你一定是走投無路了才會在這片荒蕪之地遊蕩，$c。就跟我一樣走投無路。$B$B又或者你是因為瘋了才會來這裡。就跟我一樣瘋。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2860 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2860,0,'zhTW','那可真是一場倉促的撤離，我跟你說，$c。我們把所有能拿走、能快速搬走的東西都抓了就跑。所以我們現在的補給有點吃緊。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2910 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2910,0,'zhTW','那些渾蛋趁夜襲擊我們，那時我們才剛喝了幾杯酒。不然的話，我們絕對能打贏他們，這點你可以放心。$B$B現在大家都死了……只剩下我們幾個。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2920 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2920,0,'zhTW','嘿，你好啊，$N。$B$B洛特威爾不是我遇過最敏銳的老闆。他其實對自己的工作太過投入了。投入到有時候他的僕人們甚至沒飯吃，也沒薪水拿。$B$B<盧西安對著洛特威爾皺起了眉頭。>$B$B但這不代表你就該跟著受苦。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2921 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2921,0,'zhTW','你能來真是太好了，$c。$B$B我叫魯特維爾·沃拉圖斯，是啟蒙祕法學、煉金術與工程科學協會的創始成員之一：我們致力於將艾澤拉斯的各項智慧科學融合成一套完整的學問體系。',0);
