INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3390,0,'zhTW','貧瘠之地蘊藏著豐富的物質，對我們這些羅德隆的煉藥師來說或許用得上。',0);
