INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1139,0,'zhTW','你好啊，市民。我叫鈍鼻，確切地說，是鈍鼻鎮長。我負責監督塞爾薩瑪的福祉，相信我，我們這裡永遠都需要多一雙強壯的手臂！',0);
