INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1141,0,'zhTW','如果你是為了美食而來，那就歡迎光臨！在整個暴風城……不，在整個艾澤拉斯，你都找不到比這裡更精緻的餐點！$B$B如果你是為了其他事情而來，那就請長話短說。我還有十幾道菜要準備，每一道都得顧到。',0);
