INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1267,0,'zhTW','歡迎來到雷霆啤酒釀造廠，這是由我親愛的老爸阿其勒斯·雷酒一手創立的。自從我哥哥格里姆布茲幾年前在一片醉意中失蹤之後，就一直是我在維持這裡的運作。',0);
