INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2285,0,'zhTW','我家族擁有暴風城所有貴族中最精美的珠寶與藝術品收藏！$B$B而我們也一直希望能擴大這份收藏……',0);
