INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (237,0,'zhTW','這一帶淨是麻煩事。我試著告訴那個傻瓜薩丁趁還來得及的時候趕緊離開，但他就是不聽。不過我可不傻。等我們把這輛篷車修好，我和弗娜就要立刻動身離開了。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2487 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2487,0,'zhTW','啊，聞聞這清新的鹹海風！能回到我們的家鄉港口藏寶海灣，感覺總是特別好。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2497 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2497,0,'zhTW','嗯？你找尼姆布亞有事嗎？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 253 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (253,0,'zhTW','啊哈！日安，日安，$C大人！來，坐下喝一杯吧。你的眼神中透著一股進取心，我想你會發現和我聊聊是值得的……',0);
