INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2519,0,'zhTW','哈囉！精靈們說你是來幫助我的酋長的。他們大聲地這麼說著。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2546 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2546,0,'zhTW','呀……夥計，你最好別浪費我的時間！',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 264 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (264,0,'zhTW','稍息，$C。如果你只是路過，我建議你堅持走大路，並且只在白天趕路。如果你來夜色鎮是有事要辦，不妨考慮將你的能力貢獻給守夜人。我們的技藝無庸置疑，但人手實在太少了。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 267 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (267,0,'zhTW','歡迎來到夜色鎮。書記員達爾塔為您服務。有什麼我能幫忙的嗎？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 273 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (273,0,'zhTW','把門關好，$C。誰也不知道黑騎兵什麼時候又會經過這裡。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 288 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (288,0,'zhTW','啊?!? 喔。你看起來不像迪菲亞兄弟會的小偷……也不像守夜人的一員。可憐可憐一個窮苦人吧，行嗎？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 289 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (289,0,'zhTW','嗯？你好啊，年輕的$C。周圍到處都是遊蕩的怪物，你能找到這裡來真是勇敢！$B$B既然你已經來了，或許你能幫幫一個老隱士的忙……',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2930 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2930,0,'zhTW','腐化正悄悄潛入大自然的樹林。無論付出什麼代價，都必須守護這片森林。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 294 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (294,0,'zhTW','你好，旅行者。雖然我視力不好，但我能在一哩外就感覺到$c的腳步聲。多年來我以身為暴風城的守衛者為榮，但自從視力衰退之後，我就被迫退休了。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2981 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2981,0,'zhTW','你好，$c。這些年來，我見過許多渴望向部族證明自身價值的牛頭人。但別忘了，熱忱無法取代智慧與經驗。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2988 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2988,0,'zhTW','遠行者的職責就是確保穿越莫高雷平原的旅人平安無事。任何威脅牛頭人家園安全的人，都將受到我們的懲處。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 3050 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3050,0,'zhTW','牛頭人是大地之母的兒女，我們尊重她所有的孩子。即便是我們獵殺的野獸，也同樣受到珍視，因為牠們的軀體提供養分，牠們的毛皮帶來溫暖。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 313 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (313,0,'zhTW','歡迎來到阿祖拉之塔，年輕的$C。我是塞歐克瑞圖斯。$B$B你找我有事嗎？還是……或許是我找你有事？',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 3139 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3139,0,'zhTW','Throm\'ka，$c。沒什麼時間閒聊了，還有很多工作要做。',0);
