INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3337,0,'zhTW','戰斧的重量、盟友的戰吼、噴濺到臉上的鮮血。這些正是戰士所渴望的東西，$n。我將以部落之名，用我的劍為貧瘠之地開疆闢土。',0);
