INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3338,0,'zhTW','大地、河水與天空原本都是一體的。是你的雙眼欺騙了你，讓你以為它們是分開的。大地之母就是這一切，而且遠不止如此。',0);
