INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3391,0,'zhTW','索爾為了感謝我和我的手下協助建造奧格瑪，付了我們一大筆錢，所以我就決定在這裡開個港口。我們大部分的生意都是透過藏寶海灣和大財主里維加茲進行的。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 341 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (341,0,'zhTW','我沒什麼時間閒聊，$N。我得趕在下雨之前把這座橋修好。我做的每個工程都準時完工又不超出預算，現在可不打算開始拖延進度。',0);
