INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3441,0,'zhTW','要狩獵一頭野獸，就必須了解那頭野獸。必須學習並尊重牠的生存之道。$B$B否則那就不是狩獵，只是單純的殺戮。',0);
