INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3649,0,'zhTW','黑暗勢力正侵蝕著我們的邊境，古老的汙染再度浮現，新的邪惡也不斷崛起，威脅著這片土地脆弱的平衡。在這樣黑暗的時刻，我們都必須保持警戒。',0);
