INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3666,0,'zhTW','嗯……我可以把這條線插在這裡，這樣就能驅動嘶嘶坦克裝置了，但這麼一來水力法蘭盤就需要另一個電源……也許我可以……喔，你好！嘿，想不想幫我試試一項新發明？',0);
