INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3847,0,'zhTW','梣谷是一片蒼翠繁茂、生機盎然的森林。漫步在它隱密的小徑上尋找藥草是種樂趣，但也必須小心，這片森林並非毫無危險。',0);
