INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (4046,0,'zhTW','你必須用心聆聽，年輕的$c。聆聽黑暗中的低語，因為在這動盪的時代，它們能為你指引方向。',0);
