INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (4049,0,'zhTW','石爪山之靈正在哭泣。從山巔到河流，再到那些被砍伐、垂死的樹木，無不在哭泣。',0);
