INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (4077,0,'zhTW','只要我能弄到合適的材料，我們就能製造出一些炸藥，不僅可以破壞風險投資公司的行動，還能製造混亂來分散注意力。$B$B我知道你已經印象深刻了，不過還有更精彩的呢……我很快就會告訴你更多細節。',0);
