INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (4485,0,'zhTW','日子一天天過去，這片土地上的紛爭依然看不到盡頭。不需要什麼施法者就能看出這一點。趁還來得及的時候，拿起武器吧，$c。戰爭隨時都可能降臨到我們家門口，而且如果我沒看錯的話，你正是那種樂在其中的人。',0);
