INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (4794,0,'zhTW','在塞拉摩做研究是件有趣的工作，但在這座城裡想找張軟床可真是難啊！',0);
