INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5412,0,'zhTW','半人馬氏族統治著淒涼之地的荒野。如果他們團結一致，那將會是一股可怕的力量。所幸半人馬氏族並不團結，反而彼此爭吵、互相征戰。',0);
