INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5591,0,'zhTW','這個豬圈稱不上舒適，但它有段歷史，所以斯通納德對某些人來說一定很重要。我敢打賭這就是我們留在這裡的原因。絕對不是因為風景——這裡看起來根本不像個家。',0);
