INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5637,0,'zhTW','很高興認識你，$c。我叫羅頓，我是尋物公司的負責人。$B$B我的公會專門負責找回遺失的物品。我們通常會僱用勇敢的冒險家，派他們去幫那些沒有能力或沒有時間的人完成任務。',0);
