INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5641,0,'zhTW','索爾希望處理的主要威脅是火刃氏族——那些效忠惡魔的部落成員。他們追求修習黑暗魔法，絲毫不在乎索爾對部落在卡利姆多未來的願景。',0);
