INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5767,0,'zhTW','我們唯一的希望，就是從這個已經很糟的處境中創造出一些好的結果。',0);
