INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5770,0,'zhTW','如果我們要守護自然，就必須擁抱它的力量。並且向那些試圖傷害這片土地的人展現這股力量。',0);
