INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5888,0,'zhTW','大地正在召喚你，$N。前去回應它吧，你要知道，你的同胞都以你為榮，也以你將完成的一切為榮。',0);
