INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6031,0,'zhTW','有些人受不了大熔爐的高溫，但我覺得這溫度剛剛好。而且這裡是進行正經鍛造工作的最佳場所。',0);
