INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6169,0,'zhTW','我正在探索。一場探索！一場為了打造史上最偉大發明，尋找新合金與更堅硬金屬的探索！！',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 6171 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6171,0,'zhTW','你將會一次又一次地受到環繞我們土地的黑暗所考驗，$N。但為了確保你隨時做好準備，我們會經常交付任務給你，讓你保持在自己力量的巔峰狀態。$B$B願聖光與你同在，願你永保美德。',0);
