INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6179,0,'zhTW','還有許多試煉等待著聖光的聖騎士，$N。請放心，只要你保持熱忱，堅守我們所推崇的美德，我們的道路在未來必將多次交會。',0);
