INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6569,0,'zhTW','穴居怪與麻瘋地精橫行的地方，就是我們的家園——諾姆瑞根。$B$B我們失去了家人，家園也四分五裂，流離失所。$B$B我多麼渴望回到諾姆瑞根無憂無慮的日子，但那些日子已經一去不復返了。我們必須挺身而戰！我們必須拯救諾姆瑞根！',0);
