INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (663,0,'zhTW','卡爾文家族在聖光的庇佑下為勝利而戰。而我在聖光之下的職責，就是在他們對抗不死生物的戰鬥中獻出生命。卡爾文主人交付給我一項任務，要我消滅暮色森林裡邪惡的狼人。或許你願意幫助我？',0);
