INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6946,0,'zhTW','馬蒂亞斯發現我被風險投資公司丟在貧瘠之地等死。要不是他，我早就成了潛行者的食物了。',0);
