INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (6986,0,'zhTW','我叫德蘭·杜佛斯，這邊這位是我的傻兒子瑪爾頓。如果你需要收購廢品，或是想賣掉廢品，那你就找對人了！',0);
